import React, { useState, useEffect } from "react";
import "bootstrap/dist/css/bootstrap.min.css";
import { useParams } from "react-router-dom";
import private_api from "../../server/private_api";

const LecionaAvaliacao = () => {
  const { id } = useParams();
  const [cursos, setCursos] = useState([]);
  const [avaliacoes, setAvaliacoes] = useState([]);
  const [novaAvaliacao, setNovaAvaliacao] = useState({
    titulo: "",
    descricao: "",
    dataInicio: "",
    dataFim: "",
    pontuacaoMaxima: 20,
    cursoId: "",
    tipo: "escolha_multipla",
    perguntas: [
      {
        texto: "",
        opcoes: ["", "", "", ""],
        respostaCorreta: 0,
      },
    ],
  });
  const [carregando, setCarregando] = useState(true);

  const fetchAvaliacoes = async () => {
  try {
    const avaliacoesRes = await private_api.get(
      `/professores/${id}/avaliacoes`
    );
    
    // Ajuste para o formato esperado pelo seu frontend
    const avaliacoesFormatadas = avaliacoesRes.data.map(submissao => ({
      nomeAluno: submissao.aluno?.nome || "N/A",
      idAluno: submissao.aluno?.id || "N/A",
      titulo: submissao.titulo,
      pontuacao: submissao.pontuacao,
      tempo: submissao.tempo,
      entregue: new Date(submissao.dataSubmissao).toLocaleString(),
      curso: submissao.curso?.nome || "N/A",
    }));
    
    setAvaliacoes(avaliacoesFormatadas);
  } catch (error) {
    console.error("Erro ao carregar avaliações:", error);
  } finally {
    setCarregando(false);
  }
};

  useEffect(() => {
    const fetchData = async () => {
      try {
        setCarregando(true);
        // Carrega cursos
        const cursosRes = await private_api.get(
          `/professores/${id}/listacursos`
        );
        setCursos(cursosRes.data);

        // Carrega avaliações
        await fetchAvaliacoes();
      } catch (error) {
        console.error("Erro ao carregar dados:", error);
        setCarregando(false);
      }
    };

    fetchData();

    // Configura polling para atualizar a cada 30 segundos
    const interval = setInterval(fetchAvaliacoes, 30000);
    return () => clearInterval(interval);
  }, [id]);

  // Manipuladores para perguntas de escolha múltipla
  const handleAddPergunta = () => {
    setNovaAvaliacao({
      ...novaAvaliacao,
      perguntas: [
        ...novaAvaliacao.perguntas,
        { texto: "", opcoes: ["", "", "", ""], respostaCorreta: 0 },
      ],
    });
  };

  const handleRemovePergunta = (index) => {
    const novasPerguntas = [...novaAvaliacao.perguntas];
    novasPerguntas.splice(index, 1);
    setNovaAvaliacao({
      ...novaAvaliacao,
      perguntas: novasPerguntas,
    });
  };

  const handlePerguntaChange = (index, field, value) => {
    const novasPerguntas = [...novaAvaliacao.perguntas];
    novasPerguntas[index][field] = value;
    setNovaAvaliacao({
      ...novaAvaliacao,
      perguntas: novasPerguntas,
    });
  };

  const handleOpcaoChange = (perguntaIndex, opcaoIndex, value) => {
    const novasPerguntas = [...novaAvaliacao.perguntas];
    novasPerguntas[perguntaIndex].opcoes[opcaoIndex] = value;
    setNovaAvaliacao({
      ...novaAvaliacao,
      perguntas: novasPerguntas,
    });
  };

  const handleCriarAvaliacao = async () => {
    try {
      if (!novaAvaliacao.titulo || !novaAvaliacao.cursoId) {
        alert("Preencha todos os campos obrigatórios");
        return;
      }

      // Validação das perguntas
      for (const pergunta of novaAvaliacao.perguntas) {
        if (!pergunta.texto || pergunta.opcoes.some((opcao) => !opcao)) {
          alert("Preencha todas as perguntas e opções corretamente");
          return;
        }
      }

      setCarregando(true);
      const resposta = await private_api.post("/avaliacoes", {
        ...novaAvaliacao,
        professorId: id,
        dataInicio: new Date(novaAvaliacao.dataInicio).toISOString(),
        dataFim: new Date(novaAvaliacao.dataFim).toISOString(),
      });

      if (resposta.status === 201) {
        alert("Avaliação de escolha múltipla criada com sucesso!");
        setNovaAvaliacao({
          titulo: "",
          descricao: "",
          dataInicio: "",
          dataFim: "",
          pontuacaoMaxima: 20,
          cursoId: "",
          tipo: "escolha_multipla",
          perguntas: [
            {
              texto: "",
              opcoes: ["", "", "", ""],
              respostaCorreta: 0,
            },
          ],
        });

        // Atualiza a lista de avaliações
        await fetchAvaliacoes();
      }
    } catch (error) {
      console.error("Erro ao criar avaliação:", error);
      alert(`Erro: ${error.response?.data?.error || error.message}`);
    } finally {
      setCarregando(false);
    }
  };

  return (
    <div
      className="container-fluid d-flex flex-column align-items-center"
      style={{
        backgroundColor: "#E7EFF4",
        minHeight: "100vh",
        padding: "20px",
      }}
    >
      <nav className="nav nav-tabs mb-3 bg-white p-2 w-75 d-flex justify-content-center">
        <a className="nav-link" href="#">
          Cursos
        </a>
        <a className="nav-link" href="#">
          Aulas
        </a>
        <a className="nav-link active" href="#">
          Avaliações
        </a>
      </nav>

      <h2 className="mb-3 text-center">Avaliações de Escolha Múltipla</h2>

      <div className="mb-3 w-75 d-flex justify-content-between">
        <div className="d-flex align-items-center">
          <label className="me-2">Curso:</label>
          <select
            className="form-select me-3"
            style={{ width: "200px" }}
            value={novaAvaliacao.cursoId}
            onChange={(e) =>
              setNovaAvaliacao({ ...novaAvaliacao, cursoId: e.target.value })
            }
          >
            <option value="">Selecionar curso</option>
            {cursos.map((curso) => (
              <option key={curso.id} value={curso.id}>
                {curso.nome}
              </option>
            ))}
          </select>
        </div>
        <button
          className="btn btn-primary"
          onClick={handleCriarAvaliacao}
          disabled={carregando}
        >
          {carregando ? "Criando..." : "Criar Avaliação"}
        </button>
      </div>

      <div className="bg-white p-3 rounded shadow w-75 mb-4">
        <h4>Criar Nova Avaliação</h4>
        <div className="row g-3">
          <div className="col-md-6">
            <label className="form-label">Título*</label>
            <input
              type="text"
              className="form-control"
              value={novaAvaliacao.titulo}
              onChange={(e) =>
                setNovaAvaliacao({ ...novaAvaliacao, titulo: e.target.value })
              }
              disabled={carregando}
            />
          </div>
          <div className="col-md-6">
            <label className="form-label">Pontuação Máxima</label>
            <input
              type="number"
              className="form-control"
              value={novaAvaliacao.pontuacaoMaxima}
              onChange={(e) =>
                setNovaAvaliacao({
                  ...novaAvaliacao,
                  pontuacaoMaxima: e.target.value,
                })
              }
              disabled={carregando}
            />
          </div>
          <div className="col-12">
            <label className="form-label">Descrição</label>
            <textarea
              className="form-control"
              rows="2"
              value={novaAvaliacao.descricao}
              onChange={(e) =>
                setNovaAvaliacao({
                  ...novaAvaliacao,
                  descricao: e.target.value,
                })
              }
              disabled={carregando}
            />
          </div>
          <div className="col-md-6">
            <label className="form-label">Data de Início*</label>
            <input
              type="datetime-local"
              className="form-control"
              value={novaAvaliacao.dataInicio}
              onChange={(e) =>
                setNovaAvaliacao({
                  ...novaAvaliacao,
                  dataInicio: e.target.value,
                })
              }
              disabled={carregando}
            />
          </div>
          <div className="col-md-6">
            <label className="form-label">Data de Fim*</label>
            <input
              type="datetime-local"
              className="form-control"
              value={novaAvaliacao.dataFim}
              onChange={(e) =>
                setNovaAvaliacao({ ...novaAvaliacao, dataFim: e.target.value })
              }
              disabled={carregando}
            />
          </div>
        </div>

        {/* Seção de Perguntas de Escolha Múltipla */}
        <div className="mt-4">
          <h5>Perguntas de Escolha Múltipla</h5>
          {novaAvaliacao.perguntas.map((pergunta, pIndex) => (
            <div key={pIndex} className="card mb-3">
              <div className="card-header d-flex justify-content-between align-items-center">
                <span>Pergunta {pIndex + 1}</span>
                <button
                  className="btn btn-sm btn-danger"
                  onClick={() => handleRemovePergunta(pIndex)}
                  disabled={novaAvaliacao.perguntas.length <= 1 || carregando}
                >
                  Remover
                </button>
              </div>
              <div className="card-body">
                <div className="mb-3">
                  <label className="form-label">Texto da Pergunta*</label>
                  <input
                    type="text"
                    className="form-control"
                    value={pergunta.texto}
                    onChange={(e) =>
                      handlePerguntaChange(pIndex, "texto", e.target.value)
                    }
                    disabled={carregando}
                  />
                </div>

                <label className="form-label">Opções de Resposta*</label>
                {pergunta.opcoes.map((opcao, oIndex) => (
                  <div key={oIndex} className="input-group mb-2">
                    <div className="input-group-text">
                      <input
                        type="radio"
                        name={`resposta-${pIndex}`}
                        checked={pergunta.respostaCorreta === oIndex}
                        onChange={() =>
                          handlePerguntaChange(
                            pIndex,
                            "respostaCorreta",
                            oIndex
                          )
                        }
                        disabled={carregando}
                      />
                    </div>
                    <input
                      type="text"
                      className="form-control"
                      placeholder={`Opção ${oIndex + 1}`}
                      value={opcao}
                      onChange={(e) =>
                        handleOpcaoChange(pIndex, oIndex, e.target.value)
                      }
                      disabled={carregando}
                    />
                  </div>
                ))}
              </div>
            </div>
          ))}

          <button
            type="button"
            className="btn btn-outline-primary"
            onClick={handleAddPergunta}
            disabled={carregando}
          >
            Adicionar Pergunta
          </button>
        </div>
      </div>

      <div className="bg-white p-3 rounded shadow w-75">
        <div className="d-flex justify-content-between align-items-center mb-3">
          <h4 className="mb-0">Avaliações Submetidas</h4>
          <div>
            <span className="badge bg-primary me-2">
              {avaliacoes.length} submissões
            </span>
            {carregando && (
              <div
                className="spinner-border spinner-border-sm text-primary"
                role="status"
              >
                <span className="visually-hidden">Carregando...</span>
              </div>
            )}
          </div>
        </div>

        {carregando && avaliacoes.length === 0 ? (
          <div className="text-center my-4">
            <div className="spinner-border text-primary" role="status">
              <span className="visually-hidden">Carregando...</span>
            </div>
          </div>
        ) : avaliacoes.length > 0 ? (
          <div className="table-responsive">
            <table className="table table-bordered table-hover">
              <thead className="table-light">
                <tr>
                  <th>Aluno</th>
                  <th>ID</th>
                  <th>Avaliação</th>
                  <th>Curso</th>
                  <th>Pontuação</th>
                  <th>Tempo</th>
                  <th>Entregue em</th>
                </tr>
              </thead>
              <tbody>
                {avaliacoes.map((avaliacao, index) => (
                  <tr key={index}>
                    <td>{avaliacao.nomeAluno}</td>
                    <td>{avaliacao.idAluno}</td>
                    <td>{avaliacao.titulo}</td>
                    <td>{avaliacao.curso}</td>
                    <td>{avaliacao.pontuacao}</td>
                    <td>{avaliacao.tempo}</td>
                    <td>{avaliacao.entregue}</td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        ) : (
          <div className="alert alert-info">
            Nenhuma avaliação submetida ainda
          </div>
        )}
      </div>
    </div>
  );
};

export default LecionaAvaliacao;
